_ADB_WORKER="def packaged_adb_admit():\n    global packaged_adb_chain,packaged_adb_fd\n    path=pathlib.Path(PACKAGED_REQUEST['adb']['path'])\n    packaged_adb_chain,name=parent_fds(path)\n    packaged_adb_fd=os.open(name,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK,dir_fd=packaged_adb_chain[-1]['fd'])\n    info=os.fstat(packaged_adb_fd)\n    if not stat.S_ISREG(info.st_mode) or not info.st_mode&0o111 or info.st_nlink!=1:\n        raise ValueError('packaged_read_adb_changed')\n    count,digest,pin=file_digest(packaged_adb_fd,min(overall_deadline,time.monotonic()+30))\n    if pin!=PACKAGED_REQUEST['adb']['generation'] or digest!=PACKAGED_REQUEST['adb']['sha256'] or count!=pin[2]:\n        raise ValueError('packaged_read_adb_changed')\n    packaged_adb_close()\n    for key in ('ANDROID_AVD_HOME','ANDROID_HOME','ANDROID_SDK_ROOT','LOGNAME','USER'):\n        CHILD_ENV[key]=PACKAGED_REQUEST['environment'][key]\n    CHILD_ENV['PATH']=str(path.parent)+':'+PACKAGED_REQUEST['environment']['PATH']\n    discovered=shutil.which('adb',path=CHILD_ENV['PATH'])\n    if discovered!=str(path) or not os.path.samefile(discovered,path):\n        raise ValueError('packaged_read_adb_lookup_changed')\n\ndef packaged_adb_close():\n    if packaged_adb_fd is None:raise ValueError('packaged_read_adb_changed')\n    guard_parents(packaged_adb_chain)\n    expected=PACKAGED_REQUEST['adb']['generation']\n    if fp(os.fstat(packaged_adb_fd))!=expected or fp(os.stat(pathlib.Path(PACKAGED_REQUEST['adb']['path']).name,dir_fd=packaged_adb_chain[-1]['fd'],follow_symlinks=False))!=expected:\n        raise ValueError('packaged_read_adb_changed')\n"


def _history_guard():
    if _source_bytes(Path(history.__file__))!=_HISTORY or hashlib.sha256(_HISTORY).hexdigest()!=_HISTORY_SHA:
        raise ValueError('packaged_read_history_source_changed')
    expected={}
    exec(compile(_HISTORY,str(Path(history.__file__)),'exec',dont_inherit=True),expected)
    for name,value in expected.items():
        if isinstance(value,types.FunctionType):
            actual=getattr(history,name,None)
            if not isinstance(actual,types.FunctionType) or actual.__globals__ is not history.__dict__ or actual.__code__!=value.__code__:
                raise ValueError('packaged_read_history_source_changed')
        elif name in ('CAPACITY','MAX_SNAPSHOTS','_LONG_MAX','_KEYS','_OPERATIONS','_FAILURE_CODES'):
            if getattr(history,name,None)!=value:raise ValueError('packaged_read_history_source_changed')
    if history._UUID.pattern!=expected['_UUID'].pattern or history._UUID.flags!=expected['_UUID'].flags:
        raise ValueError('packaged_read_history_source_changed')


def namespace_source(prepared):
    """Return only a currently authenticated prepared worker, never arbitrary argv.

    Execution still requires the operator's separately admitted existing ADB
    server identity, outer transport/fence, and explicit one-operation native GO.
    """
    if type(prepared)is not Prepared:raise ValueError('packaged_read_prepared_required')
    _guardian(prepared.guard)
    expected=_request({'correlationId':prepared.request['correlationId'],'owner':prepared.guard.owner,
        'revision':prepared.guard.revision,'adb':_adb_origin(prepared.guard.backend),
        'environment':copy.deepcopy(prepared.guard.backend['LAUNCH']['environment'])})
    if (prepared.request!=expected or prepared.physical!=prepared.guard.expected or prepared.stage!=prepared.guard.stage or
        hashlib.sha256(prepared.program).hexdigest()!=prepared.program_sha256 or prepared.program!=_worker_source(expected)):
        raise ValueError('packaged_read_program_changed')
    return prepared.program
